import {
  CdkTable,
  STICKY_POSITIONING_LISTENER,
} from '@angular/cdk/table';
import {coerceBooleanProperty} from '@angular/cdk/coercion';

import {assertInInjectionContext, ChangeDetectionStrategy, Component, Directive, ViewEncapsulation} from '@angular/core';

type BooleanInput = string | boolean | null | undefined;

/**
 * Enables the recycle view repeater strategy, which reduces rendering latency. Not compatible with
 * tables that animate rows.
 */
@Directive({
  standalone: false,
  selector: 'mat-table[recycleRows], table[mat-table][recycleRows]',
})
export class MatLegacyRecycleRows {
  /**
   * Current CDK selects recycling through the inherited public recycleRows input.
   * This marker directive retains the historical selector without private providers.
   * @breaking-change 17.0.0
   */
}

/**
 * Wrapper for the CdkTable with Material design styles.
 */
@Component({
  standalone: false,
  selector: 'mat-table, table[mat-table]',
  exportAs: 'matTable',
  template: `
    <ng-content select="caption"></ng-content>
    <ng-content select="colgroup, col"></ng-content>

    @if (_isServer) {
      <ng-content></ng-content>
    }

    @if (_isNativeHtmlTable) {
      <thead role="rowgroup">
        <ng-container legacyTableOutlet="header"></ng-container>
      </thead>
      <tbody role="rowgroup">
        <ng-container legacyTableOutlet="data"></ng-container>
        <ng-container legacyTableOutlet="empty"></ng-container>
      </tbody>
      <tfoot role="rowgroup">
        <ng-container legacyTableOutlet="footer"></ng-container>
      </tfoot>
    } @else {
      <ng-container legacyTableOutlet="header"></ng-container>
      <ng-container legacyTableOutlet="data"></ng-container>
      <ng-container legacyTableOutlet="empty"></ng-container>
      <ng-container legacyTableOutlet="footer"></ng-container>
    }
  `,
  styleUrls: ['table.scss'],
  host: {
    'class': 'mat-table',
    '[class.mat-table-fixed-layout]': 'fixedLayout',
    'ngSkipHydration': '',
  },
  providers: [
    {provide: CdkTable, useExisting: MatLegacyTable},
    {provide: STICKY_POSITIONING_LISTENER, useValue: null},
  ],
  encapsulation: ViewEncapsulation.None,
  // See note on CdkTable for explanation on why this uses the default change detection strategy.
  // tslint:disable-next-line:validate-decorators
  changeDetection: ChangeDetectionStrategy.Default,
})
export class MatLegacyTable<T> extends CdkTable<T> {
  constructor() {
    if (arguments.length) throw new Error('MatLegacyTable manual dependency arguments are not supported.');
    assertInInjectionContext(MatLegacyTable);
    super();
  }

  /** Preserve original coercion for direct writes as well as template inputs. */
  override get fixedLayout(): boolean { return super.fixedLayout; }
  override set fixedLayout(value: BooleanInput) {
    super.fixedLayout = coerceBooleanProperty(value);
  }

  override get multiTemplateDataRows(): boolean { return super.multiTemplateDataRows; }
  override set multiTemplateDataRows(value: BooleanInput) {
    super.multiTemplateDataRows = coerceBooleanProperty(value);
  }

  /** Overrides the sticky CSS class set by the `CdkTable`. */
  protected override stickyCssClass = 'mat-table-sticky';

  /** Overrides the need to add position: sticky on every sticky cell element in `CdkTable`. */
  protected override needsPositionStickyOnElement = false;
}
